"""Spherical U-Net with MeshConv layers in current PyTorch (CPU) -- plan row B7.2.

Port of ``SurfPostproc/common/parc/model.py`` and ``meshcnn/{ops,utils}.py`` of the BISCUIT 2.2
image (UGSCNN-style, MIT).  The architecture, layer order, channel widths, the
"pad with ones" up-sampling quirk and eval-mode batch norm follow the original; differences are
listed in ``docs/ports/parcellation-net.md``:

* the MeshConv operators are regenerated by :func:`pybiscuit.sphere.operators.build_operators`
  (no pickles); any ``level -> operator dict`` callable can be supplied instead;
* the weighted sum over ``(in_channels, 4 features)`` keeps the original broadcast multiply and
  two reductions (a single matmul is faster but differs by ~1e-4 on scores of magnitude 100),
  evaluated in blocks of 16 output channels to bound the temporary;
* every ``ResBlock`` registers each layer once (``conv1, bn1, conv2, bn2, conv3, bn3, conv_, bn_``)
  instead of twice (attribute and ``seq1``/``seq2`` position), so ``state_dict`` keys are the
  canonical names written by :mod:`pybiscuit.parc.checkpoint`.
"""

from __future__ import annotations

import math
import warnings
from collections.abc import Callable
from dataclasses import dataclass
from functools import cached_property

import numpy as np

try:
    import torch
    from torch import nn
except ImportError as exc:  # pragma: no cover - exercised only without the extra
    raise ImportError(
        "pybiscuit.parc needs PyTorch: install it with `pip install pybiscuit[parc]`"
    ) from exc

from ..sphere.operators import build_operators

__all__ = [
    "Down",
    "LevelOps",
    "MeshConv",
    "OperatorCache",
    "ResBlock",
    "SphericalUNet",
    "Up",
    "infer_architecture",
]

N_COEFF = 4  # identity, Laplacian, east-west gradient, north-south gradient


# --------------------------------------------------------------------------- operators


def _csr(m) -> torch.Tensor:
    """scipy sparse -> float32 torch CSR (``utils.sparse2tensor`` made float32 COO)."""
    c = m.tocsr()
    c.sort_indices()
    with warnings.catch_warnings():  # "Sparse CSR tensor support is in beta"
        warnings.simplefilter("ignore", UserWarning)
        return torch.sparse_csr_tensor(
            torch.from_numpy(c.indptr.astype(np.int64)),
            torch.from_numpy(c.indices.astype(np.int64)),
            torch.from_numpy(c.data.astype(np.float32)),
            size=c.shape,
        )


@dataclass(frozen=True)
class LevelOps:
    """Float32 torch operators of one icosphere level (``pkl['G','L','F2V','NS','EW']``)."""

    level: int
    nv: int
    nv_prev: int
    G: torch.Tensor  # (3*nf, nv) gradient, x/y/z blocks stacked
    L: torch.Tensor  # (nv, nv) cotangent Laplacian
    F2V: torch.Tensor  # (nv, nf) face -> vertex average
    NS: torch.Tensor  # (nf, 3)
    EW: torch.Tensor  # (nf, 3)

    @classmethod
    def from_dict(cls, level: int, ops: dict) -> LevelOps:
        return cls(
            level=level,
            nv=int(ops["V"].shape[0]),
            nv_prev=int(ops["nv_prev"]),
            G=_csr(ops["G"]),
            L=_csr(ops["L"]),
            F2V=_csr(ops["F2V"]),
            NS=torch.tensor(np.asarray(ops["NS"]), dtype=torch.float32),
            EW=torch.tensor(np.asarray(ops["EW"]), dtype=torch.float32),
        )


class OperatorCache:
    """Builds and memoises :class:`LevelOps` from an operator source.

    ``source(level)`` returns the dict of :func:`build_operators` (or of a shipped pickle read
    with the safe unpickler); the default regenerates it.
    """

    def __init__(self, source: Callable[[int], dict] | None = None):
        self._source = source or build_operators
        self._levels: dict[int, LevelOps] = {}

    def __getitem__(self, level: int) -> LevelOps:
        if level not in self._levels:
            self._levels[level] = LevelOps.from_dict(level, self._source(level))
        return self._levels[level]


def _spmm(sp: torch.Tensor, den: torch.Tensor) -> torch.Tensor:
    """``utils.spmatmul``: (B, C, nv) x sparse (n, nv) -> (B, C, n)."""
    b, c, nv = den.shape
    n = sp.shape[0]
    flat = den.permute(2, 1, 0).reshape(nv, c * b)
    res = torch.sparse.mm(sp, flat)
    return res.reshape(n, c, b).permute(2, 1, 0)


# --------------------------------------------------------------------------- layers


class MeshConv(nn.Module):
    """``ops.MeshConv`` (stride 1) and, with ``pad_ones``, ``ops.MeshConv_transpose``.

    ``pad_ones=True`` expects the previous (coarser) level's ``nv_prev`` vertices and pads the
    missing ones with **ones** before convolving (the original does this, not zero padding).
    The stride-2 branch of the original ``MeshConv`` is never instantiated by the network and is
    not ported.
    """

    OUT_CHUNK = 16  # output channels per block of the weighted sum

    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        ops: LevelOps,
        *,
        pad_ones: bool = False,
    ):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.pad_ones = pad_ones
        self.nv = ops.nv
        self.nv_prev = ops.nv_prev
        self.nv_pad = ops.nv - ops.nv_prev if pad_ones else 0
        self.bias = nn.Parameter(torch.empty(out_channels))
        self.coeffs = nn.Parameter(torch.empty(out_channels, in_channels, N_COEFF))
        stdv = 1.0 / math.sqrt(in_channels * N_COEFF)
        nn.init.uniform_(self.coeffs, -stdv, stdv)
        nn.init.uniform_(self.bias, -stdv, stdv)
        # operators are derived data, not weights: not part of the state dict
        for name in ("G", "L", "F2V", "NS", "EW"):
            self.register_buffer(name, getattr(ops, name), persistent=False)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.pad_ones:
            pad = torch.ones(*x.shape[:2], self.nv_pad, dtype=x.dtype, device=x.device)
            x = torch.cat((x, pad), dim=-1)
        b, c, nv = x.shape
        grad_face = _spmm(self.G, x)  # (B, C, 3*nf)
        grad_face = grad_face.view(b, c, 3, -1).permute(0, 1, 3, 2)  # (B, C, nf, 3)
        laplacian = _spmm(self.L, x)
        grad_ew = (grad_face * self.EW).sum(dim=-1)
        grad_ns = (grad_face * self.NS).sum(dim=-1)
        grad_vert_ew = _spmm(self.F2V, grad_ew)
        grad_vert_ns = _spmm(self.F2V, grad_ns)
        feat = torch.stack([x, laplacian, grad_vert_ew, grad_vert_ns], dim=-1)  # (B, C, nv, 4)
        # Same expression as the original (broadcast multiply, then sum over C, then over the 4
        # features) so float32 results are bit-identical to it; chunked over output channels to
        # bound the (B, O, C, nv, 4) temporary.
        feat = feat.unsqueeze(1)
        outs = []
        for o in range(0, self.out_channels, self.OUT_CHUNK):
            w = self.coeffs[o : o + self.OUT_CHUNK].unsqueeze(2)
            outs.append(torch.sum(torch.sum(torch.mul(feat, w), dim=2), dim=-1))
        out = torch.cat(outs, dim=1) if len(outs) > 1 else outs[0]
        return out + self.bias.unsqueeze(-1)


class ResBlock(nn.Module):
    """``ops.ResBlock``: 1x1 conv, MeshConv, 1x1 conv with batch norm and a skip connection.

    With ``coarsen`` the block runs on mesh ``level - 1`` and keeps only the first ``nv`` vertices
    of the finer level (``DownSamp``: icosphere vertex order is hierarchical).
    """

    def __init__(
        self,
        in_chan: int,
        neck_chan: int,
        out_chan: int,
        level: int,
        coarsen: bool,
        ops: OperatorCache,
    ):
        super().__init__()
        lvl = level - 1 if coarsen else level
        self.coarsen = coarsen
        lops = ops[lvl]
        self.nv_prev = lops.nv
        self.conv1 = nn.Conv1d(in_chan, neck_chan, kernel_size=1)
        self.bn1 = nn.BatchNorm1d(neck_chan)
        self.conv2 = MeshConv(neck_chan, neck_chan, lops)
        self.bn2 = nn.BatchNorm1d(neck_chan)
        self.conv3 = nn.Conv1d(neck_chan, out_chan, kernel_size=1)
        self.bn3 = nn.BatchNorm1d(out_chan)
        self.diff_chan = in_chan != out_chan
        if self.diff_chan or coarsen:
            self.conv_ = nn.Conv1d(in_chan, out_chan, kernel_size=1)
            self.bn_ = nn.BatchNorm1d(out_chan)

    def _down(self, x: torch.Tensor) -> torch.Tensor:
        return x[..., : self.nv_prev]

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.diff_chan or self.coarsen:
            x2 = self.conv_(x)
            if self.coarsen:
                x2 = self._down(x2)
            x2 = self.bn_(x2)
        else:
            x2 = x
        h = self.conv1(x)
        if self.coarsen:
            h = self._down(h)
        h = torch.relu(self.bn1(h))
        h = torch.relu(self.bn2(self.conv2(h)))
        h = self.bn3(self.conv3(h))
        return torch.relu(h + x2)


class Up(nn.Module):
    """``model.Up``: transposed MeshConv on the next finer mesh, concat skip, ResBlock."""

    def __init__(self, in_ch: int, out_ch: int, level: int, ops: OperatorCache):
        super().__init__()
        half_in = in_ch // 2
        self.up = MeshConv(half_in, half_in, ops[level], pad_ones=True)
        self.conv = ResBlock(in_ch, out_ch, out_ch, level, False, ops)

    def forward(self, x1: torch.Tensor, x2: torch.Tensor) -> torch.Tensor:
        x1 = self.up(x1)
        return self.conv(torch.cat([x2, x1], dim=1))


class Down(nn.Module):
    """``model.Down``: coarsening ResBlock (mesh ``level``, input on ``level + 1``)."""

    def __init__(self, in_ch: int, out_ch: int, level: int, ops: OperatorCache):
        super().__init__()
        self.conv = ResBlock(in_ch, in_ch, out_ch, level + 1, True, ops)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.conv(x)


class SphericalUNet(nn.Module):
    """``model.SphericalUNet`` (BISCUIT uses ``fdim=64, in_ch=3, max_level=5, min_level=0``).

    Input ``(B, in_ch, 20*4**max_level/2 + 2)`` icosphere features, output ``(B, out_ch, nv)``
    raw scores (pre-softmax, as ``test.py`` exports them).
    """

    def __init__(
        self,
        in_ch: int,
        out_ch: int,
        max_level: int = 5,
        min_level: int = 0,
        fdim: int = 16,
        operators: Callable[[int], dict] | OperatorCache | None = None,
    ):
        super().__init__()
        ops = operators if isinstance(operators, OperatorCache) else OperatorCache(operators)
        self.in_ch, self.out_ch = in_ch, out_ch
        self.max_level, self.min_level, self.fdim = max_level, min_level, fdim
        self.levels = max_level - min_level
        n = self.levels
        self.in_conv = MeshConv(in_ch, fdim, ops[max_level])
        self.out_conv = MeshConv(fdim, out_ch, ops[max_level])
        down = [
            Down(fdim * 2**i, fdim * 2 ** (i + 1), max_level - i - 1, ops) for i in range(n - 1)
        ]
        down.append(Down(fdim * 2 ** (n - 1), fdim * 2 ** (n - 1), min_level, ops))
        up = [Up(fdim * 2 ** (n - i), fdim * 2 ** (n - i - 2), min_level + i + 1, ops)
              for i in range(n - 1)]  # fmt: skip
        up.append(Up(fdim * 2, fdim, max_level, ops))
        self.down = nn.ModuleList(down)
        self.up = nn.ModuleList(up)

    @cached_property
    def nv(self) -> int:
        return 10 * 4**self.max_level + 2

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        xs = [self.in_conv(x)]
        for i in range(self.levels):
            xs.append(self.down[i](xs[-1]))
        x = self.up[0](xs[-1], xs[-2])
        for i in range(self.levels - 1):
            x = self.up[i + 1](x, xs[-3 - i])
        return self.out_conv(x)


def infer_architecture(state_dict: dict) -> dict:
    """Hyper-parameters from canonical-key tensor shapes (no operator needed).

    ``max_level`` comes from the face count of the first MeshConv's gradient field, which is
    not stored; it is therefore taken from the number of ``down`` blocks plus ``min_level=0``
    (BISCUIT always uses ``min_level=0``).
    """
    coeffs = state_dict["in_conv.coeffs"]
    fdim, in_ch = int(coeffs.shape[0]), int(coeffs.shape[1])
    out_ch = int(state_dict["out_conv.coeffs"].shape[0])
    n_down = len({k.split(".")[1] for k in state_dict if k.startswith("down.")})
    return {"in_ch": in_ch, "out_ch": out_ch, "fdim": fdim, "max_level": n_down, "min_level": 0}
